}

#include <assert.h>
#include <stdio.h>
#include <string.h>

void trim_in_place(char *value);

int main(void) {
    char a[] = "  blue whale  ";
    trim_in_place(a);
    assert(strcmp(a, "blue whale") == 0);

    char b[] = "blue whale  \t ";
    trim_in_place(b);
    assert(strcmp(b, "blue whale") == 0);

    char c[] = " \t\n ";
    trim_in_place(c);
    assert(strcmp(c, "") == 0);

    char d[] = "  a  b  ";
    trim_in_place(d);
    assert(strcmp(d, "a  b") == 0);

    char e[] = "blue";
    trim_in_place(e);
    assert(strcmp(e, "blue") == 0);

    char f[] = "\t  hello\tworld  ";
    trim_in_place(f);
    assert(strcmp(f, "hello\tworld") == 0);

    printf("all edge cases passed\n");
    return 0;
}

